import {ibkrPanel,ibkrMarket} from './ibkr.js';
import {money,pct,stamp,esc,selectRange,chartHTML,bindChart} from './charts.js';
const main=document.querySelector('#main');
const categories=['Crypto','Stocks','ETFs','Options','Futures','IPOs'];
let ibkr=null,ibkrAsset=null,ibkrBusy=false,lastInteraction=0;
let page='overview',category='Crypto',assetId='BTC/CAD',range='ALL',marketRange='1W',region='Canada',paper=null,market=null,errors={},busy=false,chartSeries=[];
const number=v=>Number.isFinite(v)?v.toLocaleString('en-CA',{maximumFractionDigits:8}):'—';
const signed=v=>Number.isFinite(v)?`${v>=0?'+':'−'}${money(Math.abs(v))}`:'—';
const tone=v=>v<0?'negative':'positive';
const badge=(text,type='')=>`<span class="badge ${type}">${esc(text)}</span>`;
const empty=(title,description)=>`<div class="empty"><span class="empty-icon">⌁</span><h3>${title}</h3><p>${description}</p></div>`;
const stat=(label,value,detail='',cls='')=>`<article class="stat"><span class="label">${label}</span><strong class="${cls}">${value}</strong><small>${detail}</small></article>`;
const tabs=(items,selected,attr)=>`<div class="segmented">${items.map(x=>`<button ${attr}="${x}" aria-pressed="${x===selected}" class="${x===selected?'selected':''}">${x}</button>`).join('')}</div>`;
function heartbeat(){if(!paper)return {name:'Ledger unavailable',type:'warning'};const age=Date.now()-(paper.heartbeat?.startedAt||0);return paper.halted?{name:'Risk stop active',type:'warning'}:age>paper.expectedIntervalMs*2?{name:'Worker overdue',type:'warning'}:paper.heartbeat?.status==='ok'?{name:'Worker healthy',type:'positive'}:{name:'Worker degraded',type:'warning'};}
function header(kicker,title,subtitle){return `<div class="page-heading"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${subtitle}</p></div><button id="refresh" aria-label="Refresh data" class="button" ${busy?'disabled':''}>↻ <span>${busy?'Refreshing':'Refresh'}</span></button></div>`;}
function notice(){const h=heartbeat();return `<div class="notice"><span>${badge(h.name,h.type)} ${paper?`Last cycle ${stamp(paper.heartbeat?.startedAt)} · ${paper.runtime==='Local worker'?'Separate local ledger · crypto worker not started by IBKR pilot':'Hourly, best effort'}${paper.valuationStale?' · Holdings valuation is stale':''}`:'Current balance cannot be verified.'}</span><a href="https://github.com/git-jainamshah/northstar/actions/workflows/paper-pilot.yml" target="_blank" rel="noopener">Worker logs ↗</a></div>${errors.paper?`<p class="error" role="status">${esc(errors.paper)}</p>`:''}`;}
function table(headers,rows){return `<div class="table-scroll"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`;}
function ranges(selected,attr='data-range'){return tabs(['1D','1W','1M','ALL'],selected,attr);}
function portfolio(){const r=paper;const history=selectRange(r?.history||[],range);chartSeries=[{name:'Portfolio',color:'#65ebc5',points:history.map(p=>({time:p.time,value:p.stale?null:p.equity}))}];return header('YOUR CAPITAL, IN FOCUS','Portfolio','One account. A clear view of every move.')+notice()+`<section class="hero-grid"><article class="balance"><span class="label">TOTAL EQUITY <span>CAD</span></span><div class="balance-value">${money(r?.equity)}</div><div class="balance-change ${tone(r?.pnl)}">${signed(r?.pnl)} <span>${pct(r?r.pnl/r.initialCash:null)} all time</span></div><div class="balance-foot">${badge('SIMULATED')} Started with CAD $100${r?.valuationStale?' · Stale estimate':''}</div></article><div class="stat-grid">${stat('Available cash',money(r?.cash),'CAD · ready to deploy')}${stat('Open positions',r?String(r.positions.length):'—','No leverage')}${stat('Realized P/L',signed(r?.realizedPnl),'Closed trades',tone(r?.realizedPnl))}${stat('Unrealized P/L',signed(r?.unrealizedPnl),'After estimated exit costs',tone(r?.unrealizedPnl))}</div></section><section class="panel"><div class="panel-head"><div><span class="eyebrow">PERFORMANCE</span><h2>Portfolio value</h2></div>${ranges(range)}</div>${chartHTML(chartSeries,{label:'Recorded portfolio equity in CAD, plotted by timestamp'})}<div class="panel-foot"><span><i class="legend-dot"></i> Portfolio · CAD</span><span>Recorded worker observations · gaps between cycles are not live ticks</span></div></section><div class="two-col"><section class="panel"><div class="panel-head"><h2>Holdings</h2>${badge(`${r?.positions.length??'—'} POSITIONS`)}</div>${r?r.positions.length?table(['Asset','Quantity','Value','P/L'],r.positions.map(p=>`<tr><td><b>${esc(p.id)}</b>${p.stale?'<small>Stale valuation</small>':''}</td><td>${number(p.qty)}</td><td>${money(p.liquidation)}</td><td class="${tone(p.unrealizedPnl)}">${signed(p.unrealizedPnl)}</td></tr>`)):empty('Cash is a position, too.','The strategy is waiting for an eligible setup. Your simulated capital is in CAD.'):empty('Ledger unavailable','Holdings appear once the saved account can be read.')}</section><section class="panel"><div class="panel-head"><h2>Account breakdown</h2><span class="dim">Since inception</span></div><div class="details">${detail('Starting capital',r?money(r.initialCash):'—')}${detail('Net profit / loss',signed(r?.pnl))}${detail('Simulated fees paid',money(r?.fees))}${detail('Maximum drawdown',r?`${(r.maxDrawdown*100).toFixed(2)}%`:'—')}${detail('Account opened',stamp(r?.createdAt))}</div></section></div>`;}
function detail(k,v){return `<div><span>${k}</span><strong>${v}</strong></div>`;}
function predictionPanel(r){const f=r?.forecast;const percentage=v=>Number.isFinite(v)?(v*100).toFixed(1)+'%':'—';return `<section class="panel"><div class="panel-head"><div><span class="eyebrow">PREDICTIONS → OUTCOMES</span><h2>What the model expects</h2><p>Experimental 1-hour projections · recorded before the outcome · not order instructions</p></div>${badge('SHADOW ONLY')}</div><div class="stats-row prediction-stats">${stat('Closed-trade win rate',percentage(f?.tradeWinRate),`${f?.profitableTrades??0} profitable / ${f?.closedTrades??0} closed trades`)}${stat('Forward direction accuracy',percentage(f?.directionalAccuracy),`${f?.scored??0} scored forecasts · excludes initial history`)}${stat('Predicted closed-trade P/L',signed(f?.predictedTradePnl),`${f?.matchedTrades??0} trades with a matching 1h exit`)}${stat('Actual matched P/L',signed(f?.realizedMatchedPnl),'Same trades and forecast horizon')}</div>${f?.latest?.length?table(['Instrument / plan','Upward score','Projected net P/L','Historical scenarios','Timing'],f.latest.map(p=>{const d=r.decisions.find(d=>d.asset===p.asset);return `<tr><td><b>${esc(p.asset)}</b><small>${esc(d?.action??'WAIT')} · ${esc(d?.reason??'No decision')}<br>${p.eligibleSize?'Hypothetical':'Below venue minimum'} ${money(p.cost)} position</small></td><td>${percentage(p.upwardScore)}<small>Uncalibrated direction score</small></td><td class="${tone(p.expectedPnl)}">${signed(p.expectedPnl)}<small>After estimated round-trip costs</small></td><td>${signed(p.lowPnl)} to ${signed(p.highPnl)}<small>${pct(p.lowReturn)} to ${pct(p.highReturn)} underlying return<br>5th–95th historical scenarios, not loss limits</small></td><td>${stamp(p.issuedAt)}<small>Target ${stamp(p.dueAt)} · ${esc(p.status)}${p.status==='pending'&&Date.now()>p.dueAt+120000?' · awaiting worker reconciliation':''}</small></td></tr>`})):empty('Awaiting the first forecast cycle','New predictions start with the updated worker. Past results are never assigned invented predictions.')}<div class="details">${detail('Scored shadow scenarios · expected net P/L',signed(f?.scenarioExpectedPnl))}${detail('Same shadow scenarios · observed net P/L',signed(f?.scenarioObservedPnl))}${detail('Pending / expired forecasts',`${f?.pending??0} / ${f?.expired??0}`)}${detail('Mean absolute return error',percentage(f?.meanAbsoluteReturnError))}</div><div class="panel-foot">Scenarios are hypothetical independent positions, not portfolio returns. No probability of profit is available. Outcomes require a fresh quote within 2 minutes of the 1-hour target; missed targets expire. Closed trades with different holding periods are excluded from the matched P/L comparison.</div></section>`;}
function algorithm(){const r=paper,h=selectRange(r?.history||[],range);chartSeries=[{name:'Northstar',color:'#65ebc5',points:h.map(p=>({time:p.time,value:p.stale?null:p.equity}))},{name:'BTC hold',color:'#a38aff',points:h.map(p=>({time:p.time,value:p.btc}))}];const latest=r?.decisions||[];return header('THE ENGINE ROOM','Algorithm','See the strategy, the decisions, and the outcome.')+notice()+ibkrPanel(ibkr)+predictionPanel(r)+`<div class="stats-row">${stat('Strategy','Trend v1','12h / 48h trend · rules-based')}${stat('Trading universe','CAD crypto','BTC + ETH · Kraken spot')}${stat('Executed fills',r?String(r.trades.length):'—','Latest 100 retained in this view')}${stat('Learning mode','Shadow','Learner does not place trades')}</div><section class="panel"><div class="panel-head"><div><span class="eyebrow">STRATEGY VS MARKET</span><h2>The same $100. Two outcomes.</h2></div>${ranges(range)}</div><div class="comparison"><span><i class="legend-dot"></i> Northstar <b>${money(r?.equity)}</b></span><span><i class="legend-dot violet"></i> BTC buy & hold <b>${money(r?.benchmark.btc?.lastValue)}</b></span><span class="dim">Cash baseline ${r?'$100.00':'—'}</span></div>${chartHTML(chartSeries,{label:'Northstar and Bitcoin buy-and-hold, both in CAD from the saved ledger'})}<div class="panel-foot">Both include simulated costs · matched ledger timestamps · Bitcoin is a single-asset benchmark</div></section><div class="two-col"><section class="panel"><div class="panel-head"><h2>Decision stream</h2>${badge('SAVED CYCLES')}</div><div class="decisions">${latest.slice(0,6).map(d=>`<article><div class="decision-icon ${d.action==='BUY'?'positive':d.action==='SELL'?'negative':''}">${d.action==='BUY'?'↗':d.action==='SELL'?'↘':'−'}</div><div><b>${esc(d.asset)}</b> ${badge(d.action)}<p>${esc(d.reason)}</p><small>${stamp(d.time)}</small></div></article>`).join('')||empty('No decisions available','The next successful cycle will appear here.')}</div></section><section class="panel"><div class="panel-head"><h2>Execution by asset class</h2></div><div class="details">${categories.filter(c=>c!=='IPOs').map(c=>detail(c,badge(c==='Crypto'?'Paper enabled':'Not enabled',c==='Crypto'?'positive':''))).join('')}</div><div class="rule-box"><span class="eyebrow">RISK LIMITS</span><div><span>Per position <b>$20</b></span><span>Cash reserve <b>$60</b></span><span>Daily loss stop <b>$2</b></span><span>Drawdown stop <b>5%</b></span></div><p>Stops are checked at successful cycles. Delays can cause larger losses.${r?.halted?` <strong class="negative">${esc(r.haltReason)}</strong>`:''}</p></div></section></div><section class="panel"><div class="panel-head"><h2>Trade journal</h2><span class="dim">Estimated fills · no real orders</span></div>${r?.trades.length?table(['Time','Asset','Side','Quantity','Fill price','Fee','Realized P/L'],[...r.trades].reverse().map(t=>`<tr><td>${stamp(t.time)}</td><td><b>${esc(t.asset)}</b></td><td>${badge(t.side)}</td><td>${number(t.qty)}</td><td>${money(t.price)}</td><td>${money(t.fee)}</td><td class="${tone(t.pnl)}">${signed(t.pnl)}</td></tr>`)):empty('No simulated trades yet.','When the strategy executes, the instrument, time, price, costs, and result appear here.')}</section><section class="panel"><div class="panel-head"><div><h2>Learning scorecard</h2><p>Next-hour direction · evaluated before learning · shadow only</p></div>${badge('EXPERIMENTAL')}</div>${table(['Model','Scored observations','Direction accuracy','Brier score ↓','50/50 baseline'],Object.entries(r?.models||{}).map(([id,m])=>`<tr><td><b>${esc(id)}</b></td><td>${number(m.scored)}</td><td>${Number.isFinite(m.directionalAccuracy)?(m.directionalAccuracy*100).toFixed(2)+'%':'—'}</td><td>${m.brier?.toFixed(4)??'—'}</td><td>${m.baselineBrier?.toFixed(4)??'—'}</td></tr>`))}<div class="panel-foot">Includes initial historical evaluation. Accuracy is not profitability or a calibrated chance of profit.</div></section>`;}
const coverage={Stocks:{columns:['Instrument','Venue','Last price','Change','Feed'],rows:{Canada:[['RY','Royal Bank of Canada','TSX'],['SHOP','Shopify','TSX']],US:[['AAPL','Apple','NASDAQ'],['MSFT','Microsoft','NASDAQ']]},note:'Canadian and U.S. equities need a connected market-data provider.'},ETFs:{columns:['Fund','Venue','Last price','Change','Feed'],rows:{Canada:[['VFV','Vanguard S&P 500 Index ETF','TSX'],['XEQT','iShares Core Equity ETF Portfolio','TSX']],US:[['SPY','SPDR S&P 500 ETF Trust','NYSE Arca'],['QQQ','Invesco QQQ Trust','NASDAQ']]},note:'ETF price, NAV, holdings, and distribution feeds are not connected.'},Options:{columns:['Underlying','Expiry','Strike / type','Bid / ask','Feed'],rows:{Canada:[['Canadian options','Contract chain unavailable','—']],US:[['U.S. options','Contract chain unavailable','—']]},note:'Live contract chains, Greeks, expiry, and open interest require a verified options feed. Paper execution is disabled.'},Futures:{columns:['Contract','Expiry','Last price','Volume','Feed'],rows:{Canada:[['Canadian futures','Contract directory unavailable','—']],US:[['U.S. futures','Contract directory unavailable','—']]},note:'Contract specifications, expiry, settlement, and margin data are not connected. Paper execution is disabled.'},IPOs:{columns:['Company','Exchange','Expected date','Price range','Feed'],rows:{Canada:[],US:[]},note:'A verified IPO calendar is not connected. No upcoming listings or offering dates are being inferred.'}};
function markets(){const assets=market?.assets||[],a=assets.find(a=>a.id===assetId);const bars=selectRange(a?.bars||[],marketRange);chartSeries=[{name:assetId,color:'#65ebc5',points:bars.map(b=>({time:b.time,value:b.close,volume:b.volume}))}];const prior=a?.bars?.find(b=>b.time===(a.bars.at(-1)?.time-24*3600000));const change=prior?(a.bars.at(-1).close/prior.close-1):null;return header('THE MARKET, WITHOUT THE NOISE','Markets','Explore the instruments. Know the source.')+ibkrPanel(ibkr)+`<div class="market-controls">${tabs(categories,category,'data-category')}<span class="dim">${category==='Crypto'?'CAD pairs · Kraken': 'Canada first · U.S. second'}</span></div>${category==='Crypto'?`<div class="market-layout"><aside class="panel instruments"><div class="panel-head"><h2>Instruments</h2><span class="count">2</span></div>${['BTC/CAD','ETH/CAD'].map(id=>{const q=assets.find(x=>x.id===id);return `<button class="instrument ${id===assetId?'active':''}" data-asset="${id}" aria-pressed="${id===assetId}"><span class="coin">${id.startsWith('BTC')?'₿':'Ξ'}</span><span><b>${id}</b><small>${id.startsWith('BTC')?'Bitcoin':'Ethereum'}</small></span><span class="instrument-price">${money(q?.mid)}<small>${q?'Mid price':'Unavailable'}</small></span></button>`}).join('')}<div class="feed-note"><i class="dot"></i> Public REST feed<p>Quotes refresh every 60 seconds while visible. Charts use completed 1-hour candles.</p></div></aside><section class="panel market-chart"><div class="panel-head"><div><span class="eyebrow">${esc(assetId)} <span class="dim">/ SPOT</span></span><div class="price-heading">${money(a?.mid)} <small>CAD</small></div><span class="${tone(change)}">${pct(change)} <span class="dim">24h completed-close change</span></span></div>${badge(a?(Date.now()-a.observedAt<=120000?'LIVE SNAPSHOT':'STALE'):'UNAVAILABLE',a&&Date.now()-a.observedAt<=120000?'positive':'warning')}</div><div class="chart-toolbar"><span class="dim">Close price · 1h</span>${ranges(marketRange,'data-market-range')}</div>${a?chartHTML(chartSeries,{label:`${assetId} completed hourly closing prices in CAD`,volume:true}):empty('Waiting for a valid market feed',esc(errors.market||market?.errors?.find(e=>e.id===assetId)?.message||'No verified price history is available for this instrument.'))}<div class="quote-grid">${stat('Bid',money(a?.bid),'Best displayed buy price')}${stat('Ask',money(a?.ask),'Best displayed sell price')}${stat('Spread',a?a.spreadBps.toFixed(2)+' bps':'—','Venue top of book')}</div><div class="panel-foot">${a?`${esc(a.source)} · Book ${stamp(a.observedAt)} · Latest closed bar starts ${stamp(a.bars?.at(-1)?.time)}`:'No synthetic chart or quote substitution.'}</div></section></div>${market?.errors?.length?`<p class="error">${market.errors.map(e=>esc(e.id+': '+e.message)).join(' · ')}</p>`:''}`:unavailableMarket()}<div class="bottom-note">${category==='Crypto'?'Venue-specific prices, not a consolidated market feed. Chart history and the latest quote have different timestamps.':(ibkr?.enabled?'Private IBKR pilot · Dashes mean unavailable quotes. Check feed type and receipt time.':'Instrument directory only. Dashes mean unavailable data, never zero prices.')}</div>`;}
function unavailableMarket(){const connected=ibkrMarket(ibkr,category,region,ibkrAsset);if(connected){chartSeries=connected.series;return `<div class="panel-head">${tabs(['Canada','US'],region,'data-region')}</div>`+connected.html}const c=coverage[category];return `<section class="panel"><div class="panel-head"><div><span class="eyebrow">${category.toUpperCase()} WORKSPACE</span><h2>${category==='IPOs'?'Upcoming listings':category==='Options'?'Options chain':category==='Futures'?'Futures contracts':'Market directory'}</h2></div>${tabs(['Canada','US'],region,'data-region')}</div><div class="unavailable-banner">${badge('FEED NOT CONNECTED','warning')}<p>${c.note}</p></div>${c.rows[region].length?table(c.columns,c.rows[region].map(([symbol,name,venue])=>`<tr><td><b>${esc(symbol)}</b><small>${esc(name)}</small></td><td>${esc(venue)}</td><td>—</td><td>—</td><td>${badge('Unavailable')}</td></tr>`)):''}<div class="disconnected-chart"><div class="grid-bg"></div><div><span class="empty-icon">⌁</span><h3>${category==='IPOs'?'Calendar awaiting data':'Chart awaiting data'}</h3><p>${category==='IPOs'?'Verified dates and offering prices will appear here.':'Price history will appear here once this market is connected.'}</p><span class="dim">No sample prices. No fabricated performance.</span></div></div></section>`;}
function render(){const focused=document.activeElement;const focusKey=focused?.id==='refresh'?'#refresh':null;const focusAttr=['data-range','data-market-range','data-category','data-region','data-asset','data-ibkr-asset'].find(a=>focused?.hasAttribute(a));const focusValue=focusAttr?focused.getAttribute(focusAttr):null;document.title=`Northstar · ${{overview:'Portfolio',algorithm:'Algorithm',markets:'Markets'}[page]}`;document.querySelectorAll('nav a').forEach(a=>{const active=a.dataset.page===page;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});main.innerHTML=page==='overview'?portfolio():page==='algorithm'?algorithm():markets();document.querySelector('#refresh').onclick=refresh;main.querySelectorAll('[data-range]').forEach(b=>b.onclick=()=>{range=b.dataset.range;render()});main.querySelectorAll('[data-market-range]').forEach(b=>b.onclick=()=>{marketRange=b.dataset.marketRange;render()});main.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{category=b.dataset.category;render()});main.querySelectorAll('[data-region]').forEach(b=>b.onclick=()=>{region=b.dataset.region;render()});main.querySelectorAll('[data-asset]').forEach(b=>b.onclick=()=>{assetId=b.dataset.asset;render()});main.querySelectorAll('[data-ibkr-asset]').forEach(b=>b.onclick=()=>{ibkrAsset=b.dataset.ibkrAsset;render()});bindChart(main,chartSeries);if(focusKey)main.querySelector(focusKey)?.focus({preventScroll:true});if(focusAttr)[...main.querySelectorAll(`[${focusAttr}]`)].find(b=>b.getAttribute(focusAttr)===focusValue)?.focus({preventScroll:true});const count=market?.assets?.filter(a=>Date.now()-a.observedAt<=120000).length||0;document.querySelector('#connection-status').textContent=`${count}/2 fresh crypto quotes · ${busy?'Refreshing…':'60s refresh'}`;}
async function get(url){const r=await fetch(url,{cache:'no-store',signal:AbortSignal.timeout(20000)});const data=await r.json();if(!r.ok)throw new Error(data.error||'Data feed unavailable');return data;}
async function refresh(){if(busy)return;busy=true;render();const results=await Promise.allSettled([get('/api/paper'),get('/api/market'),get('/api/ibkr')]);for(const [i,key] of ['paper','market'].entries()){const r=results[i];errors[key]=r.status==='rejected'?r.reason.message:null;if(key==='paper')paper=r.status==='fulfilled'?r.value:null;else market=r.status==='fulfilled'?r.value:null;}ibkr=results[2].status==='fulfilled'?results[2].value:null;busy=false;render();}
function route(){const next=location.hash.slice(1);page=['overview','algorithm','markets'].includes(next)?next:'overview';if(next!==page)history.replaceState(null,'',`#${page}`);render();}
document.querySelector('.skip').onclick=e=>{e.preventDefault();main.focus();main.scrollIntoView()};
window.addEventListener('hashchange',()=>{route();window.scrollTo(0,0)});document.addEventListener('visibilitychange',()=>{if(!document.hidden)refresh()});route();refresh();setInterval(()=>{if(!document.hidden)refresh()},60000);

document.addEventListener('pointerdown',()=>{lastInteraction=Date.now()});
document.addEventListener('keydown',()=>{lastInteraction=Date.now()});
setInterval(async()=>{if(Date.now()-lastInteraction<1500||document.activeElement?.classList.contains('chart-scrubber')||!ibkr?.enabled||ibkrBusy||busy||document.hidden)return;ibkrBusy=true;try{ibkr=await get('/api/ibkr')}catch{ibkr={enabled:true,connected:false,status:'connection-unavailable',assets:[]}}finally{ibkrBusy=false;if(page!=='overview'&&Date.now()-lastInteraction>=1500)render()}},2000);
